const env = typeof $env !== 'undefined' ? $env : process.env;
const body = $input.first().json.body || $input.first().json;
return [{
  json: {
    runId: body.runId,
    conversationId: body.conversationId,
    orgId: body.orgId,
    workspaceId: body.workspaceId,
    userId: body.userId,
    message: body.message || '',
    approvedPendingApprovalId: body.approvedPendingApprovalId || null,
    aiBase: env.N8N_AI_BASE_URL || 'http://ai:8083/v1/ai',
    mcpBase: env.N8N_MCP_BASE_URL || 'http://mcp:8081/v1/mcp',
    policyBase: env.N8N_POLICY_BASE_URL || 'http://policy:8085/v1/policy',
    knowledgeBase: env.N8N_KNOWLEDGE_BASE_URL || 'http://knowledge:8088/v1/knowledge',
    aiKey: env.AI_INTERNAL_API_KEY || 'dev-internal-key',
    policyKey: env.POLICY_INTERNAL_API_KEY || 'dev-internal-key',
    mcpKey: env.MCP_INTERNAL_API_KEY || 'dev-internal-key',
  },
}];

/**
 * Pure logic for Resume Prepare (HITL resume path).
 * Used by unit tests; bundled into n8n Code node via build-workflows.mjs.
 */

function normalizeHistory(historyRaw) {
  return (historyRaw || [])
    .filter((m) => m.role && m.content)
    .map((m) => ({ role: m.role, content: m.content }));
}

function buildToolContextMessage(hist) {
  const parts = [];
  let lastAssistant = null;
  for (const turn of hist) {
    if (turn.role === 'assistant') lastAssistant = turn;
    else if (turn.role === 'user' && turn.content?.trim()) parts.push(turn.content.trim());
  }
  let sb = '';
  if (lastAssistant?.content?.trim()) sb += 'Контекст ассистента: ' + lastAssistant.content.trim();
  if (parts.length) {
    if (sb) sb += '\n';
    sb += 'Запросы пользователя: ' + parts.join(' | ');
  }
  return sb;
}

function lastUserContent(hist) {
  for (let i = hist.length - 1; i >= 0; i--) {
    const t = hist[i];
    if (t.role === 'user' && t.content?.trim()) return t.content.trim();
  }
  return null;
}

function notionToolArguments(toolName, hist, fallback) {
  const n = (toolName || '').toLowerCase();
  const lastUser = lastUserContent(hist);
  if (n.includes('edit')) {
    return { find_text: '', new_text: '', message: lastUser || fallback || '' };
  }
  if (n.includes('write') || n.includes('create')) {
    const content = fallback?.trim() || lastUser || '';
    return { content, message: content, title: lastUser };
  }
  const query = lastUser || fallback || '';
  return { query, q: query, content: query, message: query };
}

function nonBlank(value) {
  return value != null && String(value).trim() !== '';
}

function hasStoredPayload(toolName, args) {
  const n = (toolName || '').toLowerCase();
  if (n.includes('edit')) {
    return (
      nonBlank(args.find_text) ||
      nonBlank(args.old_text) ||
      nonBlank(args.new_text) ||
      nonBlank(args.replace_with)
    );
  }
  if (n.includes('write') || n.includes('create')) {
    return nonBlank(args.content) || nonBlank(args.message) || nonBlank(args.title);
  }
  return nonBlank(args.query) || nonBlank(args.q) || nonBlank(args.content) || nonBlank(args.message);
}

/** После HITL — аргументы из pending approval (то, что показали пользователю на подтверждение). */
function resolveToolArguments(toolName, storedArgs, hist, fallback) {
  if (storedArgs && typeof storedArgs === 'object' && hasStoredPayload(toolName, storedArgs)) {
    return { ...storedArgs };
  }
  return notionToolArguments(toolName, hist, fallback);
}

const NOT_APPROVED = {
  skipInvoke: true,
  payload: {
    status: 'error',
    reply: 'Не удалось выполнить действие: подтверждение не найдено или уже недействительно.',
  },
};

function prepareResumeInvoke(ctx, historyRaw, pending) {
  if (!pending || pending.status !== 'approved') {
    return NOT_APPROVED;
  }

  const history = normalizeHistory(historyRaw);
  const toolName = pending.toolName;
  const connectorKey = 'notion';
  let toolMessage = buildToolContextMessage(history);
  if (!toolMessage?.trim()) toolMessage = ctx.message;
  const toolArguments = resolveToolArguments(
    toolName,
    pending.toolArguments,
    history,
    toolMessage,
  );

  return { toolName, connectorKey, toolArguments, skipInvoke: false };
}


// n8n Code node entry (bundled with resume-prepare.core.js at build time).
const ctx = $('Parse Context').first().json;
const historyRaw = $('Resume History').first().json.items || [];
const pending = $('Resume Pending').first().json;
const result = prepareResumeInvoke(ctx, historyRaw, pending);
return [{ json: result }];

const ctx = $('Parse Context').first().json;
const prep = $('Resume Prepare').first().json;
let payload = prep.payload;
if (!prep.skipInvoke) {
  const inv = $('Resume MCP').first().json;
  payload = { status: inv.ok ? 'completed' : 'error', reply: inv.ok ? inv.summary : ('Ошибка: ' + (inv.error||'failed')), toolName: prep.toolName, connectorKey: prep.connectorKey };
}
await this.helpers.httpRequest({ method:'POST', url: ctx.aiBase + '/internal/runs/' + ctx.runId + '/complete', headers:{'X-Ai-Internal-Key':ctx.aiKey,'Content-Type':'application/json'}, body: payload, json:true });
return [{ json: payload }];

/**
 * Pure logic for Prepare Route Body (chat-orchestrator).
 * Used by unit tests; bundled into n8n Code node via build-workflows.mjs.
 */
function buildRouteRequest(ctx, items) {
  let historyItems = [];
  let installations = { items: [] };
  let knowledge = { items: [] };

  for (const j of items) {
    if (Array.isArray(j.items) && j.items[0]?.role) historyItems = j.items;
    else if (Array.isArray(j.items) && j.items[0]?.connectorKey !== undefined) installations = j;
    else if (Array.isArray(j.items)) knowledge = j;
  }

  const messages = (historyItems || [])
    .filter((m) => m.role && m.content)
    .map((m) => ({ role: m.role, content: m.content }));

  const activeConnectorKeys = [];
  for (const inst of installations.items || []) {
    const st = inst.status || '';
    if (st === 'active' || st === 'error') activeConnectorKeys.push(inst.connectorKey);
  }

  const knowledgeContext = (knowledge.items || [])
    .slice(0, 5)
    .map((h) => `- ${h.title || 'doc'}: ${h.snippet || ''}`)
    .join('\n');

  return {
    ...ctx,
    routeRequest: {
      message: ctx.message,
      messages,
      activeConnectorKeys,
      knowledgeContext: knowledgeContext || null,
    },
  };
}


// n8n Code node entry (bundled with merge-for-route.core.js at build time).
const ctx = $('Parse Context').first().json;
const items = $input.all().map((i) => i.json);
return [{ json: buildRouteRequest(ctx, items) }];

// Sequential calls to chat-tool-step sub-workflow (separate n8n pipeline per step).
const env = typeof $env !== 'undefined' ? $env : process.env;
const toolStepUrl =
  env.N8N_TOOL_STEP_WEBHOOK_URL || 'http://n8n:5678/webhook/chat-tool-step';

const ctx = $('Parse Context').first().json;
const plan = $('LLM Route').first().json;
const steps = plan.steps || [];

if (!steps.length) {
  return [{ json: { skipped: true, reason: 'no steps' } }];
}

const priorResults = [];
for (let i = 0; i < steps.length; i++) {
  const step = steps[i];
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: toolStepUrl,
    json: true,
    body: {
      ...ctx,
      step,
      stepIndex: i + 1,
      totalSteps: steps.length,
      priorResults,
    },
  });

  if (res.action === 'complete') {
    return [{ json: { completedInStep: true, callback: res.callback, stepIndex: i + 1 } }];
  }

  priorResults.push({
    stepIndex: i + 1,
    connectorKey: step.connectorKey,
    toolName: step.toolName,
    label: step.label,
    ok: res.stepResult?.ok,
    summary: res.stepResult?.summary,
    error: res.stepResult?.error,
  });
}

return [{ json: { completedInStep: false, priorResults, plan } }];

/** Matches Notion page URLs (notion.so and notion.site). */
const NOTION_URL_RE =
  /https:\/\/(?:[\w-]+\.)*notion\.(?:so|site)\/[^\s)\]"'<>]+/gi;

/** @param {string} text */
function extractNotionUrls(text) {
  if (!text) {
    return [];
  }
  const seen = new Set();
  const urls = [];
  for (const match of text.matchAll(NOTION_URL_RE)) {
    const url = match[0].replace(/[.,;:!?)]+$/, '');
    if (!seen.has(url)) {
      seen.add(url);
      urls.push(url);
    }
  }
  return urls;
}

/**
 * Appends Notion links that appear in tool summaries but were dropped from the reply.
 * @param {string} reply
 * @param {Array<{ summary?: string }>|string[]} sources
 */
function ensureNotionUrlsInReply(reply, sources) {
  const texts = (sources || []).map((s) => (typeof s === 'string' ? s : s?.summary || ''));
  const urls = extractNotionUrls(texts.join('\n'));
  if (!urls.length) {
    return reply || '';
  }

  let result = (reply || '').trim();
  const missing = urls.filter((url) => !result.includes(url));
  if (!missing.length) {
    return result;
  }

  const links = missing.map((url) => `[Открыть страницу в Notion](${url})`).join('\n');
  return result ? `${result}\n\n${links}` : links;
}


import { ensureNotionUrlsInReply, extractNotionUrls } from './notion-link.core.js';

/**
 * Single successful tool step with a Notion URL — use MCP summary as-is (no LLM rewrite).
 * @param {Array<{ ok?: boolean, summary?: string }>} priorResults
 */
function shouldUseDirectSummary(priorResults) {
  if (!priorResults?.length || priorResults.length !== 1) {
    return false;
  }
  const step = priorResults[0];
  if (!step.ok) {
    return false;
  }
  return extractNotionUrls(step.summary || '').length > 0;
}

/** @param {Array<{ summary?: string }>} priorResults */
function buildDirectReply(priorResults) {
  const summary = (priorResults[0]?.summary || '').trim();
  return ensureNotionUrlsInReply(summary, priorResults);
}

/** @param {Array<{ stepIndex?: number, label?: string, toolName?: string, ok?: boolean, summary?: string, error?: string }>} priorResults */
function buildSummarizeContext(priorResults) {
  const lines = (priorResults || []).map(
    (r, i) =>
      `Шаг ${r.stepIndex ?? i + 1}: ${r.label || r.toolName} — ${r.ok ? r.summary : 'ошибка: ' + (r.error || '')}`,
  );
  return (
    'Результаты выполненных инструментов:\n' +
    lines.join('\n') +
    '\n\nСформируй краткий ответ пользователю на основе этих результатов. ' +
    'Обязательно сохрани в ответе все ссылки на страницы Notion (https://notion.so/… или https://notion.site/…) из результатов инструментов.'
  );
}

/**
 * @param {Array<{ summary?: string }>} priorResults
 * @param {string} llmReply
 */
function finalizeChainReply(priorResults, llmReply) {
  return ensureNotionUrlsInReply(llmReply || '', priorResults || []);
}


// n8n Code node entry (bundled with summarize-chain.core.js at build time).
const ctx = $('Parse Context').first().json;
const chain = $input.first().json;
const env = typeof $env !== 'undefined' ? $env : process.env;
const aiBase = env.N8N_AI_BASE_URL || 'http://ai:8083/v1/ai';
const aiKey = env.AI_INTERNAL_API_KEY || 'dev-internal-key';

const prior = chain.priorResults || [];

if (shouldUseDirectSummary(prior)) {
  return [
    {
      json: {
        status: 'completed',
        reply: buildDirectReply(prior),
        runId: ctx.runId,
        aiBase: ctx.aiBase,
        aiKey: ctx.aiKey,
      },
    },
  ];
}

const historyNode = $('Merge for Route').first().json.routeRequest?.messages || [];

const llm = await this.helpers.httpRequest({
  method: 'POST',
  url: `${aiBase}/internal/llm/complete`,
  headers: { 'X-Ai-Internal-Key': aiKey, 'Content-Type': 'application/json' },
  json: true,
  body: {
    messages: historyNode,
    mcpContext: buildSummarizeContext(prior),
    workspaceId: String(ctx.workspaceId),
  },
});

return [
  {
    json: {
      status: llm.status || 'completed',
      reply: finalizeChainReply(prior, llm.reply || ''),
      runId: ctx.runId,
      aiBase: ctx.aiBase,
      aiKey: ctx.aiKey,
    },
  },
];

